/// <summary>Routes each message to its handler's overload for its case.</summary>
internal static class ContractDispatch {
    public static void Dispatch<TContext>(this Intent message, IIntentHandler<TContext> handler, TContext context) {
        ArgumentNullException.ThrowIfNull(message);
        ArgumentNullException.ThrowIfNull(handler);
        switch (message) {
            case AdoptLegacySession @case: handler.Handle(@case, context); return;
            case ChooseSiteEngine @case: handler.Handle(@case, context); return;
            case CloseIntent @case: handler.Handle(@case, context); return;
            case CloudSyncControlIntent @case: handler.Handle(@case, context); return;
            case CloudSyncIntent @case: handler.Handle(@case, context); return;
            case CloudTransportIntent @case: handler.Handle(@case, context); return;
            case DataDeletionIntent @case: handler.Handle(@case, context); return;
            case DownloadIntent @case: handler.Handle(@case, context); return;
            case LinkIntent @case: handler.Handle(@case, context); return;
            case PageIntent @case: handler.Handle(@case, context); return;
            case PromptIntent @case: handler.Handle(@case, context); return;
            case SessionIntent @case: handler.Handle(@case, context); return;
            case SetupDraftIntent @case: handler.Handle(@case, context); return;
            case SetupFlowIntent @case: handler.Handle(@case, context); return;
            case ShortcutIntent @case: handler.Handle(@case, context); return;
            case SitePermissionIntent @case: handler.Handle(@case, context); return;
            case SpaceAccessIntent @case: handler.Handle(@case, context); return;
            case WindowIntent @case: handler.Handle(@case, context); return;
            case WorkspaceIntent @case: handler.Handle(@case, context); return;
            default: throw new ArgumentOutOfRangeException(nameof(message), message.GetType().Name, "Not a contract Intent.");
        }
    }

    public static TResult Dispatch<TContext, TResult>(this Intent message, IIntentHandler<TContext, TResult> handler, TContext context) {
        ArgumentNullException.ThrowIfNull(message);
        ArgumentNullException.ThrowIfNull(handler);
